import java.math.BigInteger;

class Solution {
    public String smallestGoodBase(String n) {
        long num = Long.parseLong(n);
        int maxM = (int) (Math.log(num) / Math.log(2));

        for (int m = maxM; m >= 2; m--) {
            long k = (long) Math.pow(num, 1.0 / m);
            if (k >= 2) {
                BigInteger bk = BigInteger.valueOf(k);
                BigInteger sum = BigInteger.ZERO;
                BigInteger term = BigInteger.ONE;
                for (int i = 0; i <= m; i++) {
                    sum = sum.add(term);
                    term = term.multiply(bk);
                }
                if (sum.equals(BigInteger.valueOf(num))) {
                    return String.valueOf(k);
                }
            }
        }
        return String.valueOf(num - 1);
    }
}

var smallestGoodBase = function(n) {
    const num = BigInt(n);
    const maxM = Math.floor(Math.log2(Number(n)));

    for (let m = maxM; m >= 2; m--) {
        const k = BigInt(Math.floor(Math.pow(Number(n), 1 / m)));
        if (k >= 2n) {
            let sum = 0n;
            let term = 1n;
            for (let i = 0; i <= m; i++) {
                sum += term;
                term *= k;
            }
            if (sum === num) return k.toString();
        }
    }
    return (num - 1n).toString();
